#!/bin/bash
# ============================================================================
# install_selection.sh -- adds the controls + selective-regeneration stages, and
# makes Stage 1 resumable/shardable so the 1,000-document run can survive a
# SLURM time limit.
#
# Run from the repo root on Bender:   bash install_selection.sh
#
# Everything it overwrites is backed up to <file>.bak.<timestamp> first, and
# every file is sha256-verified after writing. Safe to re-run.
# ============================================================================
set -euo pipefail

if [ ! -d scripts ] || [ ! -d src/probe_extraction ]; then
  echo "FATAL: run this from the NLP_Lab repo root (no scripts/ or src/ here)."
  exit 1
fi

TS=$(date +%Y%m%d-%H%M%S)
mkdir -p scripts src/probe_extraction/utils tests configs

write_file() {   # write_file <path> <sha256> <<< base64
  local path="$1" want="$2" b64 got
  b64=$(cat)
  if [ -f "$path" ]; then cp -p "$path" "${path}.bak.${TS}"; fi
  printf '%s' "$b64" | base64 -d > "$path"
  got=$(sha256sum "$path" | cut -d' ' -f1)
  if [ "$got" != "$want" ]; then
    echo "FATAL: checksum mismatch for $path"
    echo "  expected $want"
    echo "  got      $got"
    exit 1
  fi
  echo "  ok  $path"
}

echo "=== NEW FILES ==="
write_file 'scripts/10_make_figures.py' 'bd8dcf967adffb331076541bdee1218c6259be8c042239d24a77064496e5de83' <<'B64EOF'
